exercises.query:
SELECT fecha, producto, cantidad, precio_unitario
FROM ventas_kiosco
WHERE categoria = 'Bebidas' AND medio_pago = 'QR';

freePracticeTemplates.query:
SELECT a.columna, b.columna
FROM tabla_a a
JOIN tabla_b b ON a.clave = b.clave;

challenges.suggestedAnswer:
SELECT producto, cantidad, medio_pago
FROM ventas_kiosco
WHERE medio_pago = "QR";

SELECT producto, stock_actual
FROM stock_productos
WHERE stock_actual <= 10;

SELECT c.cliente, c.barrio, p.total
FROM clientes c
JOIN pedidos p ON c.cliente_id = p.cliente_id;

contextHelp.example:
SELECT producto, medio_pago
FROM ventas_kiosco
WHERE medio_pago = 'QR';

SELECT categoria, SUM(cantidad) AS unidades
FROM ventas_kiosco
GROUP BY categoria;

SELECT c.cliente, p.total
FROM clientes c
JOIN pedidos p ON c.cliente_id = p.cliente_id;
